import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const appDirectory = path.dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH
  ? path.resolve(process.env.DB_PATH)
  : path.join(appDirectory, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const addProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const addTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

const htmlPath = fileURLToPath(new URL('./public/index.html', import.meta.url));
const jsPath = fileURLToPath(new URL('./public/app.js', import.meta.url));
const cssPath = fileURLToPath(new URL('./public/style.css', import.meta.url));

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'content-type': type, 'cache-control': 'no-store' });
  res.end(body);
}
async function bodyJson(req) {
  let data = '';
  for await (const chunk of req) {
    data += chunk;
    if (data.length > 100_000) throw new Error('Request too large');
  }
  return JSON.parse(data || '{}');
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  try {
    if (req.method === 'GET' && url.pathname === '/health') return send(res, 200, JSON.stringify({ status: 'ok' }));
    if (req.method === 'GET' && url.pathname === '/api/projects') return send(res, 200, JSON.stringify(listProjects.all()));
    if (req.method === 'POST' && url.pathname === '/api/projects') {
      const data = await bodyJson(req);
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return send(res, 400, JSON.stringify({ error: 'Project name is required' }));
      const result = addProject.run(name);
      return send(res, 201, JSON.stringify({ id: Number(result.lastInsertRowid), name }));
    }
    const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskMatch && req.method === 'GET' && !taskMatch[2]) {
      const projectId = Number(taskMatch[1]);
      if (!getProject.get(projectId)) return send(res, 404, JSON.stringify({ error: 'Not found' }));
      return send(res, 200, JSON.stringify(listTasks.all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) }))));
    }
    if (taskMatch && req.method === 'POST' && !taskMatch[2]) {
      const projectId = Number(taskMatch[1]);
      if (!getProject.get(projectId)) return send(res, 404, JSON.stringify({ error: 'Not found' }));
      const data = await bodyJson(req);
      const title = typeof data.title === 'string' ? data.title.trim() : '';
      if (!title) return send(res, 400, JSON.stringify({ error: 'Task title is required' }));
      const result = addTask.run(projectId, title);
      return send(res, 201, JSON.stringify({ id: Number(result.lastInsertRowid), projectId, title, completed: false }));
    }
    if (taskMatch && req.method === 'PATCH' && taskMatch[2]) {
      const projectId = Number(taskMatch[1]);
      const data = await bodyJson(req);
      if (typeof data.completed !== 'boolean') return send(res, 400, JSON.stringify({ error: 'Invalid completion state' }));
      const result = updateTask.run(data.completed ? 1 : 0, Number(taskMatch[2]), projectId);
      return result.changes ? send(res, 200, JSON.stringify({ ok: true })) : send(res, 404, JSON.stringify({ error: 'Not found' }));
    }
    const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && projectMatch) {
      const project = getProject.get(Number(projectMatch[1]));
      return project ? send(res, 200, JSON.stringify(project)) : send(res, 404, JSON.stringify({ error: 'Not found' }));
    }
    if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
      return send(res, 200, await readFile(htmlPath, 'utf8'), 'text/html; charset=utf-8');
    }
    if (req.method === 'GET' && url.pathname === '/app.js') return send(res, 200, await readFile(jsPath, 'utf8'), 'text/javascript; charset=utf-8');
    if (req.method === 'GET' && url.pathname === '/style.css') return send(res, 200, await readFile(cssPath, 'utf8'), 'text/css; charset=utf-8');
    send(res, 404, JSON.stringify({ error: 'Not found' }));
  } catch (error) {
    send(res, error.message === 'Request too large' ? 413 : 400, JSON.stringify({ error: 'Invalid request' }));
  }
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));

function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const app = document.querySelector('#app');
const projectId = location.pathname.match(/^\/projects\/(\d+)$/)?.[1];

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

if (projectId) {
  document.querySelector('#project-form').remove();
  document.querySelector('section').remove();
  const project = await (await fetch(`/api/projects/${projectId}`)).json();
  const heading = document.querySelector('h1');
  heading.textContent = project.name || 'Project not found';
  if (!project.name) {
    heading.textContent = 'Project not found';
    return;
  }
  const back = document.createElement('button');
  back.type = 'button';
  back.textContent = 'Projects';
  back.addEventListener('click', () => { location.href = '/'; });
  app.append(back);

  const form = document.createElement('form');
  form.id = 'task-form';
  form.innerHTML = '<label for="task-title">Task title</label><div class="form-row"><input id="task-title" type="text" autocomplete="off"><button type="submit">Create task</button></div><p id="task-alert" role="alert" hidden></p>';
  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'task-filter';
  filterLabel.textContent = 'Task filter';
  const filter = document.createElement('select');
  filter.id = 'task-filter';
  for (const [value, label] of [['all', 'All'], ['open', 'Open'], ['completed', 'Completed']]) {
    const option = document.createElement('option'); option.value = value; option.textContent = label; filter.append(option);
  }
  const tasksList = document.createElement('div');
  tasksList.id = 'tasks';
  app.append(form, filterLabel, filter, tasksList);
  let tasks = [];
  async function renderTasks() {
    const response = await fetch(`/api/projects/${projectId}/tasks`);
    tasks = await response.json();
    const mode = filter.value;
    tasksList.replaceChildren();
    for (const task of tasks.filter(task => mode === 'all' || (mode === 'completed') === task.completed)) {
      const row = document.createElement('div'); row.className = 'task-row'; row.dataset.testid = 'task-row';
      const title = document.createElement('span'); title.textContent = task.title;
      const checkbox = document.createElement('input'); checkbox.type = 'checkbox'; checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        await fetch(`/api/projects/${projectId}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
        await renderTasks();
      });
      row.append(title, checkbox); tasksList.append(row);
    }
  }
  filter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const input = document.querySelector('#task-title');
    const alert = document.querySelector('#task-alert');
    const title = input.value.trim(); alert.hidden = true;
    if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
    const response = await fetch(`/api/projects/${projectId}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
    if (response.ok) { input.value = ''; await renderTasks(); }
  });
  await renderTasks();
} else {
  const list = document.querySelector('#projects');
  const alert = document.querySelector('#alert');
  async function render() {
    const projects = await loadProjects();
    list.replaceChildren();
    for (const project of projects) {
      const row = document.createElement('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.textContent = project.name;
      const open = document.createElement('button');
      open.type = 'button';
      open.textContent = 'Open project';
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      row.append(name, open);
      list.append(row);
    }
  }
  document.querySelector('#project-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const input = document.querySelector('#project-name');
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
    });
    if (response.ok) {
      input.value = '';
      await render();
    }
  });
  await render();
}

